    return -1

import math

def solve(n, edges):
    if n == 0:
        return 0

    # Initialize distance array with infinity
    dist = [math.inf] * n
    dist[0] = 0  # Starting at node 0

    # Floyd-Warshall algorithm
    for k in range(n):
        for i in range(n):
            for j in range(n):
                if dist[i] + dist[j] < dist[k]:
                    dist[k] = dist[i] + dist[j]

    # Check if the distance to node n-1 is still infinity
    if dist[n - 1] == math.inf:
        return -1
    else:
        return int(dist[n - 1])

def solve(graph, start, end):
    from collections import deque

    def bfs(node):
        visited = set()
        queue = deque([(node, 0)])
        visited.add(node)
        while queue:
            current, cost = queue.popleft()
            if current == end:
                return cost
            for neighbor, weight in graph[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append((neighbor, cost + weight))
        return -1

    return bfs(start)

