class Solution:
    def findMaximumXOR(self, nums: List[int]) -> int:
        max_num = 0
        mask = 0
        for i in range(31, -1, -1):
            mask |= (1 << i)
            prefixes = set()
            max_num |= (1 << i)
            for num in nums:
                prefixes.add(num & mask)
            temp = max_num
            for prefix in prefixes:
                if (prefix ^ temp) in prefixes:
                    max_num = temp
                    break
        return max_num

