        if p == r:
            return nums[p]
        pivot = nums[r]
        i = p
        for j in range(p, r):
            if nums[j] <= pivot:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
        nums[i], nums[r] = nums[r], nums[i]
