        if x == 0:
            return y
        if y == 0:
            return x
        return dfs(y, x % y)
    def gcd(a, b):
        return dfs(abs(a), abs(b))
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True
    def is_perfect(n):
        if n < 6:
            return False
        total = 1
        root = int(n**0.5)
        for i in range(2, root + 1):
            if n % i == 0:
                total += i
                if i != n // i:
                    total += n // i
        return total == n
