    return heapq.nsmallest(k, nums)[k - 1]

def bucket_counting(nums, k):
    min_val, max_val = min(nums), max(nums)
    buckets = [[] for _ in range(max_val - min_val + 1)]
    for num in nums:
        buckets[num - min_val].append(num)
    for bucket in buckets:
        if len(bucket) >= k:
            return bucket[k - 1]
        k -= len(bucket)
    return None

def brute_force_count(nums, k):
    count = 0
    for num in nums:
        if count < k:
            count += 1
            if count == k:
                return num
        else:
            break
    return None

