    # 3. Using a min-heap (O(n log k)): 0.2
    # 4. Using a max-heap (O(n log k)): 0.15
    # 5. Using a frequency dictionary and counting (O(n)): 0.1

    choice = random.choices([1, 2, 3, 4, 5], weights=[0.3, 0.25, 0.2, 0.15, 0.1])[0]

    if choice == 1:
        # Sorting
