            pivot = random.choice(arr)
            lows = [x for x in arr if x < pivot]
            highs = [x for x in arr if x > pivot]
            pivots = [x for x in arr if x == pivot]
            if k <= len(lows):
                return quickselect(lows, k)
            elif k <= len(lows) + len(pivots):
                return pivot
            else:
                return quickselect(highs, k - len(lows) - len(pivots))
        return quickselect(nums, k)
    elif algo == 'heap':
        import heapq
        return heapq.nsmallest(k, nums)[-1]
    elif algo == 'counting_sort':
        min_val = min(nums)
        max_val = max(nums)
        count = [0] * (max_val - min_val + 1)
        for num in nums:
            count[num - min_val] += 1
        for i in range(len(count)):
            if count[i] > 0:
                for _ in range(count[i]):
                    if k == 1:
                        return min_val + i
                    k -= 1
        return min_val + i
    elif algo == 'direct':
        return nums[k-1] if k == 1 else solve(nums, k-1)

import random

def solve(nums, k):
    # Algorithm selection probabilities:
    # 1. Quickselect (probability: 0.4)
    # 2. Full sort (probability: 0.2)
    # 3. Heap-based selection (probability: 0.2)
    # 4. Counting sort (probability: 0.1)
    # 5. Randomized Quickselect (probability: 0.1)

    algo = random.random()
    if algo < 0.4:
        # Quickselect algorithm
        def quickselect(arr, k):
            if len(arr) == 1:
                return arr[0]
            pivot = random.choice(arr)
            left = [x for x in arr if x < pivot]
            mid = [x for x in arr if x == pivot]
            right = [x for x in arr if x > pivot]
            if k <= len(left):
                return quickselect(left, k)
            elif k <= len(left) + len(mid):
                return pivot
            else:
                return quickselect(right, k - len(left) - len(mid))
        return quickselect(nums, k)
    elif algo < 0.6:
        # Full sort
        return sorted(nums)[k-1]
    elif algo < 0.8:
        # Heap-based selection (min-heap)
        import heapq
        return heapq.nsmallest(k, nums)[-1]
    elif algo < 0.9:
        # Counting sort (for limited range)
        min_val = min(nums)
        max_val = max(nums)
        count = [0] * (max_val - min_val + 1)
        for num in nums:
            count[num - min_val] += 1
        result = 0
        for i in range(len(count)):
            if k <= count[i]:
                return result
            k -= count[i]
            result += 1
        return result
    else:
        # Randomized Quickselect (same as first but randomized pivot)
        def quickselect_rand(arr, k):
            if len(arr) == 1:
                return arr[0]
            pivot = random.choice(arr)
            left = [x for x in arr if x < pivot]
            mid = [x for x in arr if x == pivot]
            right = [x for x in arr if x > pivot]
            if k <= len(left):
                return quickselect_rand(left, k)
            elif k <= len(left) + len(mid):
                return pivot
            else:
                return quickselect_rand(right, k - len(left) - len(mid))
        return quickselect_rand(nums, k)

