import math

def unique_pairs(array):
    seen = set()
    result = []
    for num in array:
        complement = num * -1
        if complement in seen:
            result.append((complement, num))
        seen.add(num)
    return result

def intersect(list1, list2):
    return [x for x in list1 if x in list2]

def get_unique_elements(array):
    seen = set()
    result = []
    for num in array:
        if num not in seen:
            seen.add(num)
            result.append(num)
    return result

def solution(nums):
    unique_nums = get_unique_elements(nums)
    pairs = unique_pairs(unique_nums)
    intersected_pairs = intersect(pairs, [(x, y) for y, x in pairs])
    return intersected_pairs

