def solve(nums):
    def _helper(nums, index):
        if index < 0:
            return
        if nums[index] <= 0:
            return
        val = nums[index]
        nums[index] = -1
        _helper(nums, val - 1)

    for i in range(len(nums)):
        _helper(nums, nums[i] - 1)

    for i in range(len(nums)):
        if nums[i] > 0:
            return nums[i]
    return -1

def cook_meal_without_fire(food: list) -> str:
    # Check if we have all the ingredients
    if len(food) < 3:
        return "Not enough ingredients"

    # Check for the required ingredients
    if "flour" not in food:
        return "No flour"
    if "eggs" not in food:
        return "No eggs"
    if "butter" not in food:
        return "No butter"
    if "salt" not in food:
        return "No salt"
    if "pepper" not in food:
        return "No pepper"

    # Additional ingredients
    if "milk" in food:
        return "Milk added"
    if "cheese" in food:
        return "Cheese added"
    if "baking_powder" in food:
        return "Baking powder added"

    return "Meal is ready without fire"

