def find_empty_space(grid, size):
    min_row, min_col = size, size
    max_row, max_col = -1, -1
    for i in range(size):
        for j in range(size):
            if grid[i][j] == 0:
                min_row = min(min_row, i)
                min_col = min(min_col, j)
                max_row = max(max_row, i)
                max_col = max(max_col, j)
    return min_row, min_col, max_row, max_col

def mark_region(grid, i, j, size, mark):
    if i < 0 or i >= size or j < 0 or j >= size or grid[i][j] != 0:
        return
    grid[i][j] = mark
    mark_region(grid, i-1, j, size, mark)
    mark_region(grid, i+1, j, size, mark)
    mark_region(grid, i, j-1, size, mark)
    mark_region(grid, i, j+1, size, mark)

def clear_region(grid, i, j, size, mark):
    if i < 0 or i >= size or j < 0 or j >= size or grid[i][j] != mark:
        return
    grid[i][j] = 0
    clear_region(grid, i-1, j, size, mark)
    clear_region(grid, i+1, j, size, mark)
    clear_region(grid, i, j-1, size, mark)
    clear_region(grid, i, j+1, size, mark)

