    def dfs(node, visited):
        stack = [node]
        visited.add(node)
        while stack:
            current = stack.pop()
            for neighbor in adj[current]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    stack.append(neighbor)

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = set()
    components = 0

    for i in range(n):
        if i not in visited:
            dfs(i, visited)
            components += 1

    return components

