def solve(grid):
    m, n = len(grid), len(grid[0])
    visited = [[False]*n for _ in range(m)]
    directions = [(-1,0),(1,0),(0,-1),(0,1)]

    def dfs(i, j):
        if i < 0 or i >= m or j < 0 or j >= n or visited[i][j]:
            return
        visited[i][j] = True
        for dx, dy in directions:
            ni, nj = i + dx, j + dy
            if grid[ni][nj] == 1:
                dfs(ni, nj)

    count = 0
    for i in range(m):
        for j in range(n):
            if grid[i][j] == 1 and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

def solve(n, edges):
    from collections import deque

    def bfs(start, adj):
        visited = set()
        queue = deque([start])
        visited.add(start)
        while queue:
            node = queue.popleft()
            for neighbor in adj[node]:
                if neighbor not in visited:
                    visited.add(neighbor)
                    queue.append(neighbor)
        return visited

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited_nodes = set()
    components = 0

    for i in range(n):
        if i not in visited_nodes:
            component = bfs(i, adj)
            visited_nodes.update(component)
            components += 1

    return components

