    from collections import defaultdict, deque

    # Build the adjacency list
    graph = defaultdict(list)
    for u, v, w in edges:
        graph[u].append((v, w))

    # Function to perform BFS for shortest path in terms of weight (Dijkstra's algorithm)
    def dijkstra(start, end):
        dist = defaultdict(lambda: float('inf'))
        dist[start] = 0
        priority_queue = [(0, start)]
        visited = set()

        while priority_queue:
            current_dist, u = heapq.heappop(priority_queue)
            if u in visited:
                continue
            visited.add(u)
            if u == end:
                return current_dist
            for v, weight in graph[u]:
                if dist[v] > current_dist + weight:
                    dist[v] = current_dist + weight
                    heapq.heappush(priority_queue, (dist[v], v))
        return float('inf')

    # Function to check if there is any path from start to end
    def has_path(start, end):
        visited = set()
        queue = deque([start])
        visited.add(start)
        while queue:
            u = queue.popleft()
            if u == end:
                return True
            for v, _ in graph[u]:
                if v not in visited:
                    visited.add(v)
                    queue.append(v)
        return False

    # Function to compute the required distance or determine if it's impossible
    def compute_distance(start, end):
        if start == end:
            return 0
        if not has_path(start, end):
            return -1
        return dijkstra(start, end)

    return compute_distance(n, edges)

