def solve(plateau, transitions, team, alice, bugs, checkpoints, start, goal):
    import heapq

    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    rows, cols = len(plateau), len(plateau[0])
    visited = [[False] * cols for _ in range(rows)]
    priority_queue = [(0, start[0], start[1], team, alice, bugs, checkpoints)]

    while priority_queue:
        cost, x, y, team, alice, bugs, checkpoints = heapq.heappop(priority_queue)

        if (x, y) == goal:
            return cost

        if visited[x][y]:
            continue
        visited[x][y] = True

        for dx, dy in dirs:
            nx, ny = x + dx, y + dy
            if 0 <= nx < rows and 0 <= ny < cols:
                if plateau[nx][ny] == '0':
                    new_cost = cost + 1
                    heapq.heappush(priority_queue, (new_cost, nx, ny, team, alice, bugs, checkpoints))
                elif plateau[nx][ny] == '1':
                    if team > 0:
                        new_cost = cost + 1
                        heapq.heappush(priority_queue, (new_cost, nx, ny, team - 1, alice, bugs, checkpoints))
                elif plateau[nx][ny] == '2':
                    if alice > 0:
                        new_cost = cost + 1
                        heapq.heappush(priority_queue, (new_cost, nx, ny, team, alice - 1, bugs, checkpoints))
                elif plateau[nx][ny] == '3':
                    if bugs > 0:
                        new_cost = cost + 1
                        heapq.heappush(priority_queue, (new_cost, nx, ny, team, alice, bugs - 1, checkpoints))
                elif plateau[nx][ny] == '4':
                    if checkpoints > 0:
                        new_cost = cost + 1
                        heapq.heappush(priority_queue, (new_cost, nx, ny, team, alice, bugs, checkpoints - 1))

    return -1

