def find_path(graph, start, goal):
    """
    Find a path from start to goal in a graph.
    Graph is represented as a dictionary where keys are nodes, and values are lists of adjacent nodes.
    """
    if not graph or start not in graph or goal not in graph:
        return None

    visited = set()
    queue = [(start, [start])]

    while queue:
        node, path = queue.pop(0)
        if node == goal:
            return path
        if node in visited:
            continue
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                queue.append((neighbor, path + [neighbor]))

    return None

