struct Point {
    int x, y;
};

bool isAdjacent(const vector<vector<int>>& grid, int row, int col, int rows, int cols) {
    if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] == 0) {
        return false;
    }
    return true;
}

vector<Point> bfs(const vector<vector<int>>& grid, int startRow, int startCol, int rows, int cols) {
    vector<vector<bool>> visited(rows, vector<bool>(cols, false));
    queue<Point> q;
    q.emplace(startRow, startCol);
    visited[startRow][startCol] = true;
    vector<Point> path;

    while (!q.empty()) {
        Point current = q.front();
        q.pop();
        path.push_back(current);

        // Check all four directions
        int directions[4][2] = {{0, 1}, {1, 0}, {0, -1}, {-1, 0}};
        for (const auto& dir : directions) {
            int newRow = current.x + dir[0];
            int newCol = current.y + dir[1];
            if (isAdjacent(grid, newRow, newCol, rows, cols) && !visited[newRow][newCol]) {
                visited[newRow][newCol] = true;
                q.emplace(newRow, newCol);
            }
        }
    }
    return path;
}

