int main() {
    int n, m;
    std::cin >> n >> m;
    std::vector<std::vector<char>> grid(n, std::vector<char>(m, ' '));
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            std::cin >> grid[i][j];
        }
    }

    std::vector<std::pair<int, int>> start;
    std::vector<std::pair<int, int>> man;
    std::vector<std::pair<int, int>> baby;

    // Parse input to get start, man, baby positions
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'S') start.emplace_back(i, j);
            else if (grid[i][j] == 'M') man.emplace_back(i, j);
            else if (grid[i][j] == 'B') baby.emplace_back(i, j);
        }
    }

    // Avoid man, house (S?), and baby
    std::unordered_set<Point> forbidden;
    for (const auto& p : man) forbidden.insert(Point(p.first, p.second));
    for (const auto& p : baby) forbidden.insert(Point(p.first, p.second));

    // BFS from start to reach the door
    std::vector<std::vector<bool>> visited(n, std::vector<bool>(m, false));
    std::queue<std::pair<int, int>> q;
    q.push(start[0]);
    visited[start[0].first][start[0].second] = true;

    std::vector<std::vector<int>> dist(n, std::vector<int>(m, -1));
    dist[start[0].first][start[0].second] = 0;

    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();

        for (const auto& [dx, dy] : directions) {
            int nx = x + dx;
            int ny = y + dy;
            if (nx >= 0 && nx < n && ny >= 0 && ny < m && !visited[nx][ny] && grid[nx][ny] != '#' && !forbidden.contains(Point(nx, ny))) {
                visited[nx][ny] = true;
                dist[nx][ny] = dist[x][y] + 1;
                q.push({nx, ny});
            }
        }
    }

    int min_steps = 1e9;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            if (grid[i][j] == 'D' && dist[i][j] != -1) {
                min_steps = std::min(min_steps, dist[i][j]);
            }
        }
    }

    if (min_steps == 1e9) {
        std::cout << "-1\n";
    } else {
        std::cout << min_steps << "\n";
    }

    return 0;
}

