from typing import List, Tuple

def find_cycle_and_length(data: List[Tuple[int, int]]) -> Tuple[bool, int]:
    """
    Finds if the graph has a cycle (using a simple DFS), and if so, returns (True, length of the cycle)
    if not, returns (False, 0)
    """
    from collections import defaultdict

    # Build the graph
    graph = defaultdict(list)
    for u, v in data:
        graph[u].append(v)
        graph[v].append(u)

    visited = set()
    parent = {}

    def dfs(node: int) -> bool:
        """DFS to detect if a cycle exists starting at `node`."""
        if node in visited:
            return False
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                parent[neighbor] = node
                if dfs(neighbor):
                    return True
            elif parent.get(node, None) != neighbor:
                # Found a cycle
                cycle = []
                current = node
                while current != neighbor:
                    cycle.append(current)
                    current = parent[current]
                cycle.append(neighbor)
                return True
        return False

    # Check for cycle starting from each unvisited node
    for node in graph:
        if node not in visited:
            if dfs(node):
                # Find the length of the cycle
                cycle = []
                current = node
                while current != neighbor:
                    cycle.append(current)
                    current = parent[current]
                cycle.append(neighbor)
                return (True, len(cycle))
    return (False, 0)

