def has_eight_queens_valid(board):
    n = len(board)
    # Check rows
    if any(row.count('Q') > 1 for row in board):
        return False

    # Check columns
    for col in range(n):
        if any(board[row][col] == 'Q' for row in range(n)):
            return False

    # Check diagonals
    for row in range(n):
        for col in range(n):
            if board[row][col] == 'Q':
                # Check top-left to bottom-right diagonal
                i, j = row - 1, col - 1
                while i >= 0 and j >= 0:
                    if board[i][j] == 'Q':
                        return False
                    i -= 1
                    j -= 1
                # Check bottom-left to top-right diagonal
                i, j = row + 1, col + 1
                while i < n and j < n:
                    if board[i][j] == 'Q':
                        return False
                    i += 1
                    j += 1
                # Check top-right to bottom-left diagonal
                i, j = row - 1, col + 1
                while i >= 0 and j < n:
                    if board[i][j] == 'Q':
                        return False
                    i -= 1
                    j += 1
                # Check bottom-right to top-left diagonal
                i, j = row + 1, col - 1
                while i < n and j >= 0:
                    if board[i][j] == 'Q':
                        return False
                    i += 1
                    j -= 1
    return True

def simulate_gridTraversal(n):
    grid = []
    for i in range(n):
        row = []
        for j in range(n):
            if i == 0 and j == 0:
                row.append(0)  # Start
            elif i == n - 1 and j == n - 1:
                row.append(2)  # Goal
            elif (i + j) % 3 == 0:
                row.append(1)  # Obstacle
            else:
                row.append(3)  # Empty cell
        grid.append(row)

    visited = [[False for _ in range(n)] for _ in range(n)]
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def dfs(x, y):
        if x < 0 or y < 0 or x >= n or y >= n or visited[x][y] or grid[x][y] == 1:
            return False
        if grid[x][y] == 2:
            return True
        visited[x][y] = True
        for dx, dy in directions:
            if dfs(x + dx, y + dy):
                return True
        return False

    return dfs(0, 0)

