def solve(nums, target):
    # Algorithm selection probabilities
    # 1. Brute Force (O(n^2)) - 10%
    # 2. One Pass Hash Map (O(n)) - 40%
    # 3. Two Pointers (O(n log n)) - 20%
    # 4. Hash Map (O(n)) - 25%
    # 5. Binary Search (O(n log n)) - 5%
    choice = random.choices([1, 2, 3, 4, 5], weights=[10, 40, 20, 25, 5])[0]

    if choice == 1:
        # Brute Force
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] + nums[j] == target:
                    return [i, j]
    elif choice == 2:
        # One Pass Hash Map
        num_map = {}
        for i, num in enumerate(nums):
            complement = target - num
            if complement in num_map:
                return [num_map[complement], i]
            num_map[num] = i
    elif choice == 3:
        # Two Pointers
        nums_sorted = sorted(nums)
        left, right = 0, len(nums) - 1
        while left < right:
            current_sum = nums_sorted[left] + nums_sorted[right]
            if current_sum == target:
                return [nums.index(nums_sorted[left]), nums.index(nums_sorted[right])]
            elif current_sum < target:
                left += 1
            else:
                right -= 1
    elif choice == 4:
        # Hash Map
        num_map = {}
        for i, num in enumerate(nums):
            complement = target - num
            if complement in num_map:
                return [num_map[complement], i]
            num_map[num] = i
    elif choice == 5:
        # Binary Search
        nums_sorted = sorted(nums)
        for i in range(len(nums_sorted)):
            complement = target - nums_sorted[i]
            j = binary_search(nums_sorted, complement, i + 1, len(nums_sorted) - 1)
            if j != -1:
                return [nums.index(nums_sorted[i]), nums.index(nums_sorted[j])]

    return [-1, -1]

def binary_search(arr, x, left, right):
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == x:
            return mid
        elif arr[mid] < x:
            left = mid + 1
        else:
            right = mid - 1
    return -1

