import random

def solve(nums):
    # Algorithm choices and their probabilities
    algorithms = [
        ("Floyd's Tortoise and Hare (Cycle Detection)", 0.3),
        ("Hash Table / Dictionary", 0.25),
        ("Binary Search on Frequencies", 0.2),
        ("Brute Force with Counting", 0.15),
        ("Using Sum of Arithmetic Series", 0.1)
    ]

    # Select an algorithm at random based on probabilities
    selected = random.choices([a[0] for a in algorithms], weights=[a[1] for a in algorithms])[0]

    if selected == "Floyd's Tortoise and Hare (Cycle Detection)":
        # Floyd's Cycle-Finding Algorithm
        slow = nums[0]
        fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        # Find the entrance to the cycle
        slow = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

    elif selected == "Hash Table / Dictionary":
        seen = {}
        for num in nums:
            if num in seen:
                return num
            seen[num] = True

    elif selected == "Binary Search on Frequencies":
        low, high = 1, len(nums)
        while low < high:
            mid = (low + high) // 2
            count = 0
            for num in nums:
                if num <= mid:
                    count += 1
            if count > mid:
                low = mid + 1
            else:
                high = mid
        return low

    elif selected == "Brute Force with Counting":
        for i in range(len(nums)):
            if nums.count(nums[i]) > 1:
                return nums[i]

    elif selected == "Using Sum of Arithmetic Series":
        expected_sum = len(nums) * (len(nums) + 1) // 2
        actual_sum = sum(nums)
        return actual_sum - expected_sum

