    if chosen_algorithm == "Floyd's Tortoise and Hare (Cycle Detection)":
        # Floyd's Tortoise and Hare algorithm to find the duplicate
        slow = nums[0]
        fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        # Find the entrance to the cycle
        slow = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

    elif chosen_algorithm == "Hash Map / Dictionary":
        # Use a dictionary to track seen numbers
        seen = {}
        for num in nums:
            if num in seen:
                return num
            seen[num] = True

    elif chosen_algorithm == "Binary Search on Frequency":
        # Binary search on the range [1, n]
        low, high = 1, len(nums) - 1
        while low < high:
            mid = (low + high) // 2
