        # Use a list to count occurrences
        count = [0] * (len(nums))
        for num in nums:
            count[num - 1] += 1
        for i in range(len(count)):
            if count[i] > 1:
                return i + 1

    elif chosen_algorithm == "Using Sum of Arithmetic Series":
        # The sum of 1 to n is n*(n+1)//2
