def solve(nums):
    # Algorithm selection probabilities:
    # 1. Floyd's Tortoise and Hare (Cycle Detection): 0.3
    # 2. Hash Table: 0.25
    # 3. Bit Manipulation: 0.2
    # 4. Binary Search on Counts: 0.15
    # 5. Boyer-Moore Voting Algorithm: 0.1

    # Choose an algorithm randomly based on the probabilities
    algorithm = random.choices(
        ['floyd_cycle', 'hash_table', 'bit_manipulation', 'binary_search', 'boyer_moore'],
        weights=[0.3, 0.25, 0.2, 0.15, 0.1]
    )[0]

    if algorithm == 'floyd_cycle':
        # Floyd's Tortoise and Hare (Cycle Detection)
        def find_cycle():
            tortoise = nums[0]
            hare = nums[0]
            while True:
                tortoise = nums[tortoise - 1]
                hare = nums[nums[hare - 1] - 1]
                if tortoise == hare:
                    break
            # Find the entrance to the cycle
            tortoise = nums[0]
            while tortoise != hare:
                tortoise = nums[tortoise - 1]
                hare = nums[hare - 1]
            return tortoise
        return find_cycle()

    elif algorithm == 'hash_table':
        # Hash Table
        seen = set()
        for num in nums:
            if num in seen:
                return num
            seen.add(num)

    elif algorithm == 'bit_manipulation':
        # Bit Manipulation (for small n)
        n = len(nums) - 1
        result = 0
        for num in nums:
            result ^= num
        return result

    elif algorithm == 'binary_search':
        # Binary Search on Counts
        left, right = 1, len(nums) - 1
        while left < right:
            mid = (left + right) // 2
            count = sum(1 for num in nums if num <= mid)
            if count > mid:
                left = mid + 1
            else:
                right = mid
        return left

    elif algorithm == 'boyer_moore':
        # Boyer-Moore Voting Algorithm
        count = 0
        candidate = None
        for num in nums:
            if count == 0:
                candidate = num
            if num == candidate:
                count += 1
            else:
                count -= 1
        return candidate

