def solve(nums):
    # Algorithm choices and their probabilities
    algorithms = [
        ("Floyd's Tortoise and Hare (Cycle Detection)", 0.3),
        ("Hash Map (Dictionary)", 0.25),
        ("Binary Search on Frequency", 0.15),
        ("Visited Tracking (with List)", 0.15),
        ("Brute Force (Nested Loop)", 0.15)
    ]

    # Select an algorithm at random based on probabilities
    selected = random.choices([a[0] for a in algorithms], weights=[a[1] for a in algorithms])[0]

    if selected == "Floyd's Tortoise and Hare (Cycle Detection)":
        # Floyd's Cycle-Finding Algorithm (Tortoise and Hare)
        slow = nums[0]
        fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        # Find the entrance to the cycle
        ptr1 = nums[0]
        ptr2 = slow
        while ptr1 != ptr2:
            ptr1 = nums[ptr1]
            ptr2 = nums[ptr2]
        return ptr1

    elif selected == "Hash Map (Dictionary)":
        # Use a dictionary to track seen numbers
        seen = {}
        for num in nums:
            if num in seen:
                return num
            seen[num] = True

    elif selected == "Binary Search on Frequency":
        # Binary search on possible values
        low, high = 1, len(nums)
        while low < high:
            mid = (low + high) // 2
            count = 0
            for num in nums:
                if num <= mid:
                    count += 1
            if count > mid:
                low = mid + 1
            else:
                high = mid
        return low

    elif selected == "Visited Tracking (with List)":
        # Track visited elements using a list
        visited = [False] * (len(nums) + 1)
        for num in nums:
            if visited[num]:
                return num
            visited[num] = True

    elif selected == "Brute Force (Nested Loop)":
        # Check each element against all others
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] == nums[j]:
                    return nums[i]

