        def find_cycle():
            slow = nums[0]
            fast = nums[0]
            while True:
                slow = nums[slow - 1]
                fast = nums[nums[fast - 1] - 1]
                if slow == fast:
                    break
            ptr1 = nums[0]
            ptr2 = slow
            while ptr1 != ptr2:
                ptr1 = nums[ptr1 - 1]
                ptr2 = nums[ptr2 - 1]
            return ptr1
        return find_cycle()
    elif algorithm == 2:
        # Hash Table (Set)
