        # Binary Search on Frequencies
        low, high = 1, len(nums)
        while low < high:
            mid = (low + high) // 2
            count = 0
            for num in nums:
                if num <= mid:
                    count += 1
            if count > mid:
                low = mid + 1
            else:
                high = mid
        return low
    elif algorithm == 4:
        # Boyer-Moore Voting Algorithm
        count = 0
        candidate = 0
        for num in nums:
            if count == 0:
                candidate = num
            count += 1 if num == candidate else -1
        return candidate
    elif algorithm == 5:
