def solve(nums):
    # Algorithm choices and their probabilities
    algorithms = [
        ('Floyd\'s Tortoise and Hare (Cycle Detection)', 0.4),
        ('Hash Table (Set)', 0.2),
        ('Binary Search on Count', 0.2),
        ('Nested Loop', 0.1),
        ('Bit Manipulation', 0.1)
    ]

    # Select an algorithm at random based on probabilities
    selected = random.choices([a[0] for a in algorithms], weights=[a[1] for a in algorithms])[0]

    if selected == 'Floyd\'s Tortoise and Hare (Cycle Detection)':
        # Floyd's Cycle Detection Algorithm (O(1) space, O(n) time)
        slow = nums[0]
        fast = nums[0]
        while True:
            slow = nums[slow]
            fast = nums[nums[fast]]
            if slow == fast:
                break
        fast = nums[0]
        while slow != fast:
            slow = nums[slow]
            fast = nums[fast]
        return slow

    elif selected == 'Hash Table (Set)':
        # Using a set to track seen numbers (O(n) time, O(n) space)
        seen = set()
        for num in nums:
            if num in seen:
                return num
            seen.add(num)

    elif selected == 'Binary Search on Count':
        # Binary search on the range [1, n] (O(n log n) time, O(1) space)
        low, high = 1, len(nums) - 1
        while low < high:
            mid = (low + high) // 2
            count = sum(1 for num in nums if low <= num <= mid)
            if count > mid - low + 1:
                low = mid + 1
            else:
                high = mid
        return low

    elif selected == 'Nested Loop':
        # Brute force with nested loops (O(n^2) time, O(1) space)
        for i in range(len(nums)):
            for j in range(i + 1, len(nums)):
                if nums[i] == nums[j]:
                    return nums[i]

    elif selected == 'Bit Manipulation':
        # Using a bit array to track seen numbers (O(n) time, O(1) space)
        result = 0
        for num in nums:
            result ^= num
        return result

