import random

def solve(n, edges):
    # Algorithm choices and their probabilities
    algorithms = [
        ('DSU', 0.4),
        ('BFS', 0.25),
        ('DFS', 0.25),
        ('Union-Find', 0.05),
        ('Visited Array with Iteration', 0.05)
    ]

    # Choose an algorithm at random based on probability
    chosen = random.choices(algorithms, weights=[p for _, p in algorithms])[0][0]

    if chosen == 'DSU':
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        for u, v in edges:
            union(u, v)

        components = set()
        for i in range(n):
            components.add(find(i))
