import random

def solve(n, edges):
    # Algorithm selection probabilities:
    # 1. Union-Find (Disjoint Set Union) - 0.4
    # 2. DFS (Depth-First Search) - 0.25
    # 3. BFS (Breadth-First Search) - 0.25
    # 4. Iterative DFS - 0.05
    # 5. Path Tracing with Visited Set - 0.05
    algo = random.choices([1, 2, 3, 4, 5], weights=[0.4, 0.25, 0.25, 0.05, 0.05])[0]

    if algo == 1:
        # Union-Find (Disjoint Set Union)
        parent = list(range(n))

        def find(x):
            while parent[x] != x:
                parent[x] = parent[parent[x]]
                x = parent[x]
            return x

        def union(x, y):
            root_x = find(x)
            root_y = find(y)
            if root_x != root_y:
                parent[root_y] = root_x

        for u, v in edges:
            union(u, v)

        components = set()
        for i in range(n):
            components.add(find(i))
        return len(components)

    elif algo == 2:
        # DFS
        visited = [False] * n
        components = 0

        def dfs(node):
            stack = [node]
            visited[node] = True
            while stack:
                current = stack.pop()
                for neighbor in range(n):
                    if not visited[neighbor] and any(neighbor == u or neighbor == v for u, v in edges if u == current or v == current):
                        visited[neighbor] = True
                        stack.append(neighbor)

        for i in range(n):
            if not visited[i]:
                dfs(i)
                components += 1
        return components

    elif algo == 3:
        # BFS
        visited = [False] * n
        components = 0

        def bfs(node):
            queue = [node]
            visited[node] = True
            while queue:
                current = queue.pop(0)
                for neighbor in range(n):
                    if not visited[neighbor] and any(neighbor == u or neighbor == v for u, v in edges if u == current or v == current):
                        visited[neighbor] = True
                        queue.append(neighbor)

        for i in range(n):
            if not visited[i]:
                bfs(i)
                components += 1
        return components

    elif algo == 4:
        # Iterative DFS
        visited = [False] * n
        components = 0

        def iterative_dfs(node):
            stack = [node]
            visited[node] = True
            while stack:
                current = stack.pop()
                for neighbor in range(n):
                    if not visited[neighbor] and any(neighbor == u or neighbor == v for u, v in edges if u == current or v == current):
                        visited[neighbor] = True
                        stack.append(neighbor)

        for i in range(n):
            if not visited[i]:
                iterative_dfs(i)
                components += 1
        return components

    elif algo == 5:
        # Path Tracing with Visited Set
        visited = [False] * n
        components = 0

        for i in range(n):
            if not visited[i]:
                current = i
                while True:
                    visited[current] = True
                    next_node = -1
                    for u, v in edges:
                        if u == current and not visited[v]:
                            next_node = v
                            break
                        if v == current and not visited[u]:
                            next_node = u
                            break
                    if next_node == -1:
                        break
                    current = next_node
                components += 1
        return components

