def solve(n, edges):
    # Algorithm Selection: 
    # 1. Union-Find (Probability: 0.4)
    # 2. DFS (Probability: 0.2)
    # 3. BFS (Probability: 0.2)
    # 4. Disjoint Set Union (Probability: 0.15)
    # 5. Iterative DFS (Probability: 0.05)
    algorithm = random.choices([1, 2, 3, 4, 5], weights=[0.4, 0.2, 0.2, 0.15, 0.05])[0]

    if algorithm == 1:
        # Union-Find (Path Compression and Union by Rank)
        parent = list(range(n))
        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u
        def union(u, v):
            pu, pv = find(u), find(v)
            if pu != pv:
                parent[pu] = pv
        for u, v in edges:
            union(u, v)
        components = set()
        for i in range(n):
            components.add(find(i))
        return len(components)
    elif algorithm == 2:
        # DFS (Recursive)
        visited = [False] * n
        def dfs(u):
            visited[u] = True
            for v in range(n):
                if not visited[v] and [u, v] in edges or [v, u] in edges:
                    dfs(v)
        count = 0
        for i in range(n):
            if not visited[i]:
                dfs(i)
                count += 1
        return count
    elif algorithm == 3:
        # BFS
        visited = [False] * n
        from collections import deque
        count = 0
        for i in range(n):
            if not visited[i]:
                count += 1
                queue = deque([i])
                visited[i] = True
                while queue:
                    u = queue.popleft()
                    for v in range(n):
                        if not visited[v] and ([u, v] in edges or [v, u] in edges):
                            visited[v] = True
                            queue.append(v)
        return count
    elif algorithm == 4:
        # Disjoint Set Union (Similar to Union-Find)
        parent = list(range(n))
        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u
        def union(u, v):
            pu, pv = find(u), find(v)
            if pu != pv:
                parent[pu] = pv
        for u, v in edges:
            union(u, v)
        components = set()
        for i in range(n):
            components.add(find(i))
        return len(components)
    elif algorithm == 5:
        # Iterative DFS
        visited = [False] * n
        count = 0
        for i in range(n):
            if not visited[i]:
                count += 1
                stack = [i]
                visited[i] = True
                while stack:
                    u = stack.pop()
                    for v in range(n):
                        if not visited[v] and ([u, v] in edges or [v, u] in edges):
                            visited[v] = True
                            stack.append(v)
        return count

