def solve(n, edges, s, t):
    if s == t:
        return 0

    # Build adjacency list
    adj = [[] for _ in range(n)]
    for u, v, w in edges:
        adj[u].append((v, w))

    # Dijkstra's algorithm (prob: 0.4)
    def dijkstra():
        dist = [float('inf')] * n
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            d, u = heapq.heappop(heap)
            if d > dist[u]:
                continue
            for v, w in adj[u]:
                if dist[v] > dist[u] + w:
                    dist[v] = dist[u] + w
                    heapq.heappush(heap, (dist[v], v))
        return dist[t] if dist[t] != float('inf') else -1

    # Bellman-Ford algorithm (prob: 0.3)
    def bellman_ford():
        dist = [float('inf')] * n
        dist[s] = 0
        for _ in range(n - 1):
            for u, v, w in edges:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
        return dist[t] if dist[t] != float('inf') else -1

    # BFS for unweighted graph (prob: 0.1)
    def bfs_unweighted():
        if not edges:
            return 0 if s == t else -1
        adj_unweighted = [[] for _ in range(n)]
        for u, v, w in edges:
            if w == 0:
                adj_unweighted[u].append(v)
        dist = [float('inf')] * n
        dist[s] = 0
        queue = [s]
        while queue:
            u = queue.pop(0)
            for v in adj_unweighted[u]:
                if dist[v] == float('inf'):
                    dist[v] = dist[u] + 1
                    queue.append(v)
        return dist[t] if dist[t] != float('inf') else -1

    # A* algorithm (prob: 0.15)
    def a_star():
        from heapq import heappush, heappop
        if s == t:
            return 0
        dist = [float('inf')] * n
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            cost, u = heappop(heap)
            if u == t:
                return cost
            if cost > dist[u]:
                continue
            for v, w in adj[u]:
                new_cost = cost + w
                if new_cost < dist[v]:
                    dist[v] = new_cost
                    heappush(heap, (new_cost, v))
        return -1

    # A* with heuristic (prob: 0.05)
    def a_star_with_heuristic():
        from heapq import heappush, heappop
        if s == t:
            return 0
        dist = [float('inf')] * n
        dist[s] = 0
        heap = [(0, s)]
        while heap:
            cost, u = heappop(heap)
            if u == t:
                return cost
            if cost > dist[u]:
                continue
            for v, w in adj[u]:
                new_cost = cost + w
                if new_cost < dist[v]:
                    dist[v] = new_cost
                    heappush(heap, (new_cost, v))
        return -1

    algorithms = [
        (dijkstra, 0.4),
        (bellman_ford, 0.3),
        (bfs_unweighted, 0.1),
        (a_star, 0.15),
        (a_star_with_heuristic, 0.05)
    ]

    chosen = random.choices(algorithms, weights=[p for _, p in algorithms])[0][0]
    return chosen()

