        visited[node] = True
        recursion_stack[node] = True

        for neighbor in adj[node]:
            if not visited[neighbor]:
                if has_cycle_util(neighbor, visited, recursion_stack, adj):
                    return True
            elif recursion_stack[neighbor]:
                return True

        recursion_stack[node] = False
        return False

    adj = [[] for _ in range(n)]
    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    visited = [False] * n
    recursion_stack = [False] * n

    for i in range(n):
        if not visited[i]:
            if has_cycle_util(i, visited, recursion_stack, adj):
                return True

    return False

def solve(n, edges):
    def visit(node, parent):
        for neighbor in graph[node]:
            if neighbor == parent:
                continue
            if visited[neighbor]:
                return True
            if visit(neighbor, node):
                return True
        return False

    graph = [[] for _ in range(n)]
    for u, v in edges:
        graph[u].append(v)
        graph[v].append(u)

    visited = [False] * n
    for i in range(n):
        if not visited[i]:
            if visit(i, -1):
                return True
    return False

