import random

def solve(n, edges):
    # Algorithm choices and their probabilities:
    # 1. DFS-based cycle detection (probability 0.4)
    # 2. Union-Find (Disjoint Set Union) (probability 0.3)
    # 3. Topological sort (probability 0.15)
    # 4. BFS-based cycle detection (probability 0.1)
    # 5. Checking for self-loop (probability 0.05)

    algorithm = random.choices([1, 2, 3, 4, 5], weights=[0.4, 0.3, 0.15, 0.1, 0.05])[0]

    if algorithm == 1:
        # DFS-based cycle detection
        visited = [False] * n
        rec_stack = [False] * n

        def dfs(u):
            if not visited[u]:
                visited[u] = True
                rec_stack[u] = True
                for v in adj[u]:
                    if not visited[v]:
                        if dfs(v):
                            return True
                    elif rec_stack[v]:
                        return True
                rec_stack[u] = False
            return False

        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)

        for i in range(n):
            if not visited[i]:
                if dfs(i):
                    return True
        return False
    elif algorithm == 2:
        # Union-Find (Disjoint Set Union)
        parent = list(range(n))

        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u

        def union(u, v):
            pu, pv = find(u), find(v)
            if pu == pv:
                return True
            parent[pu] = pv
            return False

        for u, v in edges:
            if union(u, v):
                return True
        return False
    elif algorithm == 3:
        # Topological sort (for directed graphs, but this is undirected)
        # Not suitable for undirected graphs, but implemented anyway
        # For undirected graphs, this may not work correctly
        in_degree = [0] * n
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
            adj[v].append(u)
            in_degree[u] += 1
            in_degree[v] += 1

        queue = [i for i in range(n) if in_degree[i] == 0]
        count = 0
        while queue:
            u = queue.pop(0)
            count += 1
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)
        return count != n
    elif algorithm == 4:
        # BFS-based cycle detection
        visited = [False] * n
        for i in range(n):
            if not visited[i]:
                queue = [(i, -1)]  # (current node, parent)
                visited[i] = True
                while queue:
                    u, parent = queue.pop(0)
                    for v in adj[u]:
                        if not visited[v]:
                            visited[v] = True
                            queue.append((v, u))
                        elif v != parent:
                            return True
        return False
    else:
        # Check for self-loop (cycle of length 1, which is not possible per input constraints)
        return False

