    # 2. Union-Find (Disjoint Set Union) (0.3)
    # 3. BFS-based cycle detection (0.15)
    # 4. Topological Sorting (0.1)
    # 5. Checking for back edges in DFS (0.05)
    algorithms = [
        ('dfs', 0.4),
        ('union_find', 0.3),
        ('bfs', 0.15),
        ('topological_sort', 0.1),
        ('dfs_back_edges', 0.05)
    ]
