        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)

        count = 0
        while queue:
            node = queue.popleft()
            count += 1
            for neighbor in graph[node]:
                in_degree[neighbor] -= 1
                if in_degree[neighbor] == 0:
                    queue.append(neighbor)

        return count != n

    elif algo == 5:
        # Hash-based edge counting (for simple cycle check in complete graph)
        # This is not reliable for general graphs, but used for the sake of the exercise
        edge_set = set()
        for u, v in edges:
