def solve(n, edges):
    # Helper to build adjacency list
    def build_graph():
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u].append(v)
            graph[v].append(u)
        return graph

    # Helper to detect cycle using DFS
    def has_cycle_dfs(node, visited, recursion_stack, graph):
        visited[node] = True
        recursion_stack[node] = True

        for neighbor in graph[node]:
            if not visited[neighbor]:
                if has_cycle_dfs(neighbor, visited, recursion_stack, graph):
                    return True
            elif recursion_stack[neighbor]:
                return True

        recursion_stack[node] = False
        return False

    # Helper to detect cycle using Union-Find
    def has_cycle_uf():
        parent = list(range(n))
        def find(u):
            while parent[u] != u:
                parent[u] = parent[parent[u]]
                u = parent[u]
            return u
        def union(u, v):
            root_u = find(u)
            root_v = find(v)
            if root_u == root_v:
                return True
            parent[root_v] = root_u
            return False
        for u, v in edges:
            if union(u, v):
                return True
        return False

    # Helper to detect cycle using BFS
    def has_cycle_bfs():
        visited = [False] * n
        for i in range(n):
            if not visited[i]:
                queue = [(i, -1)]
                visited[i] = True
                while queue:
                    node, parent = queue.pop(0)
                    for neighbor in range(n):
                        if graph[node][neighbor]:
                            if neighbor == parent:
                                continue
                            if visited[neighbor]:
                                return True
                            visited[neighbor] = True
                            queue.append((neighbor, node))
        return False

    # Helper to detect cycle using DFS with visited array
    def has_cycle_dfs2():
        visited = [False] * n
        for i in range(n):
            if not visited[i]:
                stack = [(i, -1, False)]
                while stack:
                    node, parent, processed = stack.pop()
                    if processed:
                        continue
                    if visited[node]:
                        return True
                    visited[node] = True
                    stack.append((node, parent, True))
                    for neighbor in graph[node]:
                        if neighbor != parent:
                            stack.append((neighbor, node, False))
        return False

    # Helper to detect cycle using topological sort
    def has_cycle_topo():
        graph = [[] for _ in range(n)]
        in_degree = [0] * n
        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1
        queue = [i for i in range(n) if in_degree[i] == 0]
        count = 0
        while queue:
            u = queue.pop(0)
            count += 1
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)
        return count != n

    # Choose an algorithm based on probabilities
    algorithms = [
        ('dfs', 0.3),
        ('uf', 0.25),
        ('bfs', 0.2),
        ('dfs2', 0.15),
        ('topo', 0.1)
    ]
    chosen = random.choices([a[0] for a in algorithms], weights=[a[1] for a in algorithms])[0]

