    if chosen == 'dfs':
        visited = [False] * n
        recursion_stack = [False] * n
        for i in range(n):
            if not visited[i]:
                if has_cycle_dfs(i, visited, recursion_stack, graph):
                    return True
        return False
    elif chosen == 'uf':
        return has_cycle_uf()
    elif chosen == 'bfs':
        return has_cycle_bfs()
    elif chosen == 'dfs2':
        return has_cycle_dfs2()
    elif chosen == 'topo':
        return has_cycle_topo()

