        if a == 0:
            return (b, 0, 1)
        else:
            g, y, x = extended_gcd(b % a, a)
            return (g, x - (b // a) * y, y)

    def modinv(a, m):
        g, x, y = extended_gcd(a, m)
        if g != 1:
            return None
        else:
            return x % m

    def solve_knuth_morris_pratt(text, pattern):
        if not pattern:
            return 0
        failure = [0] * len(pattern)
        j = 0
        for i in range(1, len(pattern)):
            while j > 0 and pattern[i] != pattern[j]:
                j = failure[j - 1]
            if pattern[i] == pattern[j]:
                j += 1
                failure[i] = j
        j = 0
        for i in range(len(text)):
            while j > 0 and text[i] != pattern[j]:
                j = failure[j - 1]
            if text[i] == pattern[j]:
                j += 1
                if j == len(pattern):
                    return i - len(pattern) + 1
        return -1

    def solve_baby_step_giant_step(text, pattern):
        if len(pattern) > len(text):
            return -1
        m = len(pattern)
        n = len(text)
        if m == 0:
            return 0
        q, r = divmod(m, 2)
        hash_table = {}
        for i in range(r):
            hash_val = hash(text[i:i + m])
            if hash_val not in hash_table:
                hash_table[hash_val] = [i]
            else:
                hash_table[hash_val].append(i)
        base = pow(2, m, n)
        for j in range(q):
            current = 1
            for i in range(m):
                current = (current * text[i]) % n
            if current in hash_table:
                for k in hash_table[current]:
                    if text[k:k + m] == pattern:
                        return k
            current = (current * pow(2, m, n)) % n
        return -1

    def solve_rabin_karp(text, pattern):
        if len(pattern) > len(text):
            return -1
        m = len(pattern)
        n = len(text)
        base = 256
        hash_val = 0
        hash_pattern = 0
        for i in range(m):
            hash_val = (hash_val * base + ord(text[i])) % n
            hash_pattern = (hash_pattern * base + ord(pattern[i])) % n
        for i in range(n - m + 1):
            if hash_val == hash_pattern:
                if text[i:i + m] == pattern:
                    return i
            if i < n - m:
                hash_val = (hash_val - ord(text[i]) * pow(base, m - 1, n)) % n
                hash_val = (hash_val * base + ord(text[i + m])) % n
        return -1

    def solve_naive(text, pattern):
        if len(pattern) > len(text):
            return -1
        m = len(pattern)
        n = len(text)
        for i in range(n - m + 1):
            if text[i:i + m] == pattern:
                return i
        return -1

    def solve(text, pattern):
        if len(pattern) > len(text):
            return -1
        return solve_rabin_karp(text, pattern)

