    def matrix_pow(matrix, power):
        result = [[1, 0], [0, 1]]  # Identity matrix
        while power > 0:
            if power % 2 == 1:
                result = matrix_mult(result, matrix)
            matrix = matrix_mult(matrix, matrix)
            power //= 2
        return result

    def matrix_mult(a, b):
        return [
            [a[0][0]*b[0][0] + a[0][1]*b[1][0], a[0][0]*b[0][1] + a[0][1]*b[1][1]],
            [a[1][0]*b[0][0] + a[1][1]*b[1][0], a[1][0]*b[0][1] + a[1][1]*b[1][1]]
        ]

    if n == 0:
        return 0
    elif n == 1:
        return 1

    def fib_matrix(n):
        if n == 0:
            return [[1, 0], [0, 1]]
        elif n == 1:
            return [[1, 1], [1, 0]]
        else:
            return matrix_mult(fib_matrix(n-1), fib_matrix(n-2))

    mat = fib_matrix(n)
