def solve():
    import sys
    import random

    def topological_sort(graph, num_nodes):
        in_degree = [0] * num_nodes
        for node in graph:
            for neighbor in graph[node]:
                in_degree[neighbor] += 1

        queue = [i for i in range(num_nodes) if in_degree[i] == 0]
        result = []

        while queue:
            u = queue.pop(0)
            result.append(u)
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)

        return result if len(result) == num_nodes else []

    def build_graph(prerequisites):
        graph = {}
        for a, b in prerequisites:
            if a not in graph:
                graph[a] = []
            graph[a].append(b)
        return graph

    def get_random_order(result):
        random.shuffle(result)
        return result

    def main():
        input_lines = sys.stdin.read().splitlines()
        n = int(input_lines[0])
        prerequisites = [tuple(map(int, line.split())) for line in input_lines[1:]]

        graph = build_graph(prerequisites)
        result = topological_sort(graph, n)
        if not result:
            print([])
        else:
            print(get_random_order(result))

    main()

