def solve():
    import sys
    sys.setrecursionlimit(10000)

    def dfs(node, visited, stack, graph, in_degree):
        visited.add(node)
        for neighbor in graph[node]:
            if neighbor not in visited:
                dfs(neighbor, visited, stack, graph, in_degree)
        stack.append(node)

    def topological_sort(graph, in_degree):
        visited = set()
        stack = []
        for node in graph:
            if node not in visited:
                dfs(node, visited, stack, graph, in_degree)
        return stack[::-1]

    def solve_helper(n, graph, in_degree):
        result = topological_sort(graph, in_degree)
        if len(result) != n:
            return []
        return result

    def parse_prerequisites(prerequisites):
        graph = {}
        in_degree = {}
        for a, b in prerequisites:
            if a not in graph:
                graph[a] = []
            if b not in graph:
                graph[b] = []
            graph[a].append(b)
            in_degree[a] = in_degree.get(a, 0) + 1
            in_degree[b] = in_degree.get(b, 0) + 1
        return graph, in_degree

    def solve_problem(n, prerequisites):
        graph, in_degree = parse_prerequisites(prerequisites)
        for i in range(n):
            if i not in graph:
                graph[i] = []
            if i not in in_degree:
                in_degree[i] = 0
        result = solve_helper(n, graph, in_degree)
        return result if len(result) == n else []

    def func(n, prerequisites):
        return solve_problem(n, prerequisites)

    return func

