import heapq

def solve():
    def topological_sort(adj, n):
        in_degree = [0] * n
        for u in range(n):
            for v in adj[u]:
                in_degree[v] += 1
        heap = [i for i in range(n) if in_degree[i] == 0]
        heapq.heapify(heap)
        result = []
        while heap:
            u = heapq.heappop(heap)
            result.append(u)
            for v in adj[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    heapq.heappush(heap, v)
        return result if len(result) == n else []

    def dfs(node, visited, order, adj):
        visited[node] = True
        for neighbor in adj[node]:
            if not visited[neighbor]:
                dfs(neighbor, visited, order, adj)
        order.append(node)

    def get_order(adj, n):
        visited = [False] * n
        order = []
        for i in range(n):
            if not visited[i]:
                dfs(i, visited, order, adj)
        return order[::-1]

    def main():
        import sys
        input = sys.stdin.read
        data = input().split()
        idx = 0
        n = int(data[idx])
        idx += 1
        edges = []
        while idx < len(data):
            u = int(data[idx])
            v = int(data[idx + 1])
            edges.append((u, v))
            idx += 2
        adj = [[] for _ in range(n)]
        for u, v in edges:
            adj[u].append(v)
        order = get_order(adj, n)
        return order

    return main

