    def topological_sort(n, edges):
        from collections import defaultdict, deque
        graph = defaultdict(list)
        in_degree = [0] * n
        for u, v in edges:
            graph[u].append(v)
            in_degree[v] += 1
        queue = deque()
        for i in range(n):
            if in_degree[i] == 0:
                queue.append(i)
