        while queue:
            u = queue.popleft()
            result.append(u)
            for v in graph[u]:
                in_degree[v] -= 1
                if in_degree[v] == 0:
                    queue.append(v)
        return result if len(result) == n else []

    def find_cycle(n, edges):
        visited = [False] * n
        recursion_stack = [False] * n

        def dfs(u):
            visited[u] = True
            recursion_stack[u] = True
            for v in edges[u]:
                if not visited[v]:
                    if dfs(v):
                        return True
                elif recursion_stack[v]:
                    return True
            recursion_stack[u] = False
            return False

        for i in range(n):
            if not visited[i]:
                if dfs(i):
                    return True
        return False

    def find_order(n, edges):
        if find_cycle(n, edges):
            return []
        return topological_sort(n, edges)

    return find_order

