import random

def solve(intervals):
    if not intervals:
        return []

    # Ensure that the intervals are not empty and start <= end
    for interval in intervals:
        if interval[0] > interval[1]:
            raise ValueError("Invalid interval: start > end")

    # Shuffle intervals to ensure randomness
    random.shuffle(intervals)

    # Use a set to track which intervals are used
    used = set()

    # Process intervals in a way that ensures no overlap
    while True:
        # Find the first unused interval
        first = None
        for i, interval in enumerate(intervals):
            if i not in used:
                first = i
                break

        if first is None:
            break

        used.add(first)
        start, end = intervals[first]

        # Check all other intervals and mark those that overlap or touch with the current one
        for i in range(len(intervals)):
            if i not in used and intervals[i][0] <= end and intervals[i][1] >= start:
                used.add(i)

    # Collect all used intervals
    result = [intervals[i] for i in used]

    # Sort the result by start
    result.sort()

    return result

