def solve(nums):
    def extend_sequence(seq, num):
        if not seq or num > seq[-1]:
            seq.append(num)
            return True
        return False

    def find_next_sequence(seq, num):
        left, right = 0, len(seq)
        while left < right:
            mid = (left + right) // 2
            if seq[mid] < num:
                left = mid + 1
            else:
                right = mid
        if left < len(seq):
            seq[left] = num
        return left

    if not nums:
        return 0

    sequences = [nums[0]]
    for num in nums[1:]:
        if extend_sequence(sequences[0], num):
            continue
        else:
            for seq in sequences:
                if find_next_sequence(seq, num) < len(seq):
                    break
            else:
                sequences.append([num])
    return max(len(seq) for seq in sequences)

